import re

ACTION_RE = re.compile(r"Action:\s*(\w+)\[(.*?)\]", re.DOTALL)
FINAL_RE = re.compile(r"Final Answer:\s*(.*)", re.DOTALL)

PARSE_HELP = "Couldn't parse your action; use the format tool[input]"


def react(question, llm, tools, max_steps=6):
    scratchpad = f"Question: {question}\n"
    for step in range(1, max_steps + 1):
        text = llm(scratchpad)
        cut = text.find("Observation:")
        if cut != -1:
            text = text[:cut]
        scratchpad += text

        final = FINAL_RE.search(text)
        if final:
            return {"answer": final.group(1).strip(), "steps": step,
                    "scratchpad": scratchpad, "stopped": "final"}

        action = ACTION_RE.search(text)
        if action is None:
            observation = PARSE_HELP
        else:
            name, argument = action.group(1), action.group(2)
            if name not in tools:
                available = ", ".join(sorted(tools))
                observation = f"Unknown tool {name!r}. Available: {available}"
            else:
                try:
                    observation = str(tools[name](argument))
                except Exception as exc:
                    observation = f"Error: {exc}"
        scratchpad += f"\nObservation: {observation}\n"
    return {"answer": None, "steps": max_steps,
            "scratchpad": scratchpad, "stopped": "max_steps"}
